#include <WiFi.h>
#include <HTTPClient.h>
#include <driver/i2s.h>

// ─── WiFi credentials ───
const char* ssid     = "YOUR_WIFI_SSID";
const char* password = "YOUR_WIFI_PASS";

// ─── Music server URL ───
// Points to a local server that streams raw PCM audio
// The server should return audio as: 16-bit, 44100 Hz, stereo, signed LE
const char* streamUrl = "http://10.152.232.1:5000/guest";

// ─── I2S Configuration for MAX98357A ───
#define I2S_PORT       I2S_NUM_0
#define I2S_BCLK_PIN   26   // Bit Clock
#define I2S_LRCK_PIN   25   // Word Select (LRC)
#define I2S_DOUT_PIN   22   // Serial Data Out

// ─── Buffer settings ───
#define I2S_BUF_SIZE   1024
#define I2S_BUF_COUNT  4

void setupI2S() {
  i2s_config_t i2s_config = {
    .mode                 = (i2s_mode_t)(I2S_MODE_MASTER | I2S_MODE_TX),
    .sample_rate          = 44100,
    .bits_per_sample      = I2S_BITS_PER_SAMPLE_16BIT,
    .channel_format       = I2S_CHANNEL_FMT_RIGHT_LEFT,
    .communication_format = I2S_COMM_FORMAT_STAND_I2S,
    .intr_alloc_flags     = ESP_INTR_FLAG_LEVEL1,
    .dma_buf_count        = I2S_BUF_COUNT,
    .dma_buf_len          = I2S_BUF_SIZE,
    .use_apll             = false,
    .tx_desc_auto_clear   = true,
  };

  i2s_pin_config_t pin_config = {
    .bck_io_num   = I2S_BCLK_PIN,
    .ws_io_num    = I2S_LRCK_PIN,
    .data_out_num = I2S_DOUT_PIN,
    .data_in_num  = I2S_PIN_NO_CHANGE,
  };

  i2s_driver_install(I2S_PORT, &i2s_config, 0, NULL);
  i2s_set_pin(I2S_PORT, &pin_config);
  i2s_zero_dma_buffer(I2S_PORT);
  Serial.println("[MUSIC] I2S initialized");
}

void setup() {
  Serial.begin(115200);
  delay(1000);
  Serial.println("\n=== ESP32 I2S Online Music Player ===");

  // Connect to WiFi
  Serial.printf("[WIFI] Connecting to %s", ssid);
  WiFi.begin(ssid, password);
  while (WiFi.status() != WL_CONNECTED) {
    delay(500);
    Serial.print(".");
  }
  Serial.printf("\n[WIFI] Connected! IP: %s\n", WiFi.localIP().toString().c_str());

  // Initialize I2S
  setupI2S();
  Serial.println("[MUSIC] Ready to stream music...");
}

void streamAudio() {
  HTTPClient http;
  http.begin(streamUrl);
  http.setTimeout(10000);

  int httpCode = http.GET();
  if (httpCode != HTTP_CODE_OK) {
    Serial.printf("[MUSIC] Server error: %d\n", httpCode);
    http.end();
    return;
  }

  Serial.printf("[MUSIC] Streaming from %s\n", streamUrl);

  WiFiClient* stream = http.getStreamPtr();
  uint8_t buffer[I2S_BUF_SIZE];
  size_t totalPlayed = 0;

  while (stream->connected() && stream->available()) {
    int bytesRead = stream->readBytes(buffer, sizeof(buffer));
    if (bytesRead <= 0) continue;

    size_t bytesWritten = 0;
    i2s_write(I2S_PORT, buffer, bytesRead, &bytesWritten, portMAX_DELAY);
    totalPlayed += bytesWritten;

    // Print progress every 100KB
    if ((totalPlayed / 102400) != ((totalPlayed - bytesWritten) / 102400)) {
      Serial.printf("[MUSIC] Played %.1f KB\n", totalPlayed / 1024.0);
    }
  }

  Serial.printf("[MUSIC] Stream finished (%.2f MB)\n", totalPlayed / 1048576.0);
  http.end();
}

void loop() {
  if (WiFi.status() != WL_CONNECTED) {
    Serial.println("[WIFI] Disconnected. Reconnecting...");
    WiFi.reconnect();
    while (WiFi.status() != WL_CONNECTED) delay(500);
  }

  Serial.println("[MUSIC] Starting playback...");
  streamAudio();

  Serial.println("[MUSIC] Waiting 2s before next stream...");
  delay(2000);
}
